         "1 - أهم رواد فكر الأنوار بفرنسا",
         "- تعاقب على حكم فرنسا خلال ق 18 ثلاث ملوك (لويس 14-15-16) مارسوا حكم استبدادي بدعم من الكنيسة و النبلاء، وعرفت فرنسا مجموعة من الأزمات الاقتصادية والاجتماعية وبروز مجموعة من المفكرين الذين حاولوا تغير الأوضاع العامة بأفكارهم منهم :"
