         "- الكارثة الطبيعية: مجموعة من الخسائر المادية والبشرية الناتجة عن حادث مفاجئ طبيعي مع إن أثر الخسائر لأية كارثة لا يتعلق فقط بقوى طبيعية بل بعوامل إنسانية مثل طراز البناء وفعالية الوقاية المتخذة في المنطقة المعنية وترتبط أهمية هذه الخسائر بمدى قدرة المجتمع على توقع حدوث الكوارث والاحتماء منها مثل الفيضانات، الجفاف، البراكين، حريق الغابات، الاعصارات والزلازل........",
